 R.x_fire = { t: 'Get away from the car and call for help', c: 'stop', why: 'Smoke, flames or a burning smell can turn into a vehicle fire quickly.', step: 'If you can do it safely, turn the car off. Get everyone out and move well away from the car and from traffic. Call emergency services.', safe: 'Don’t go back for belongings. Don’t open the hood — fresh air can make a fire grow.', diff: 'emergency', drive: 'no' };
  R.x_fuel = { t: 'Possible fuel leak — do not start the car', c: 'stop', why: 'Leaking fuel or strong fuel vapor can ignite from a spark, a hot part, or a cigarette.', step: 'Don’t start or crank the engine. Keep flames, sparks and cigarettes away. If fuel is pooling or the smell is strong, move away and call emergency services or a tow service.', safe: 'Don’t try to find or fix a fuel leak yourself.', diff: 'pro', drive: 'no', need: 'Fuel system leak inspection before any start attempt' };
  R.x_brakes = { t: 'Brakes may be failing — stop as safely as you can', c: 'stop', why: 'A pedal that sinks or feels very soft, or a car that won’t stop well, can mean brake fluid is leaking or the brake system has failed.', step: 'If you are moving: turn on hazard lights, pump the brake pedal firmly, shift to a lower gear, gently apply the parking brake, and steer to a safe place. Once stopped, do not drive — have the car towed.', safe: 'Do not drive until a professional has inspected the brakes.', diff: 'emergency', drive: 'no', need: 'Brake hydraulic system inspection' };
  R.x_steam = { t: 'Overheating — pull over and let it cool', c: 'stop', why: 'Steam from under the hood usually means coolant is boiling or leaking onto hot parts.', step: 'Pull over safely and turn the engine off. Don’t open the hood until the steam stops. Wait at least 30 minutes, then use the “Engine overheating” section of this app.', safe: 'Never open the radiator or coolant cap while the engine is hot — hot coolant can spray out and cause serious burns.', diff: 'emergency', drive: 'no' };
  R.x_hot = { t: 'Pull over and turn the engine off', c: 'stop', why: 'Driving with an overheating engine can cause severe and expensive engine damage.', step: 'As soon as it’s safe, pull over and switch the engine off. Turning the heater to full hot with the fan on high can pull some heat away from the engine while you find a place to stop. Then wait at least 30 minutes and start this section again.', safe: 'Don’t open the hood if you see steam. Never open the coolant cap while hot.', diff: 'emergency', drive: 'no' };
  R.x_spot = { t: 'Get yourself to safety first', c: 'stop', why: 'Your safety matters more than the car.', step: 'Turn on the hazard lights. If traffic is close and you can get out on the side away from traffic, move well off the road, behind a barrier if there is one. If getting out isn’t safe, stay buckled in. Call roadside assistance or emergency services, then come back to this app once you’re safe.', diff: 'emergency', drive: 'no' };
  R.x_hv = { t: 'High-voltage danger — do not touch', c: 'stop', why: 'Hybrid and electric cars carry voltage that can cause serious injury. Damage from crashes or flooding can also lead to battery fires, sometimes hours or days later.', step: 'Don’t touch orange cables or damaged parts. Don’t try to drive, start or charge the car. If there is smoke, popping or hissing, or the car was underwater, move away and call emergency services. Otherwise contact the manufacturer’s roadside assistance.', safe: 'Only trained high-voltage technicians should work on these systems.', diff: 'pro', drive: 'no', need: 'High-voltage system inspection by a trained technician' };
  R.x_battery = { t: 'Damaged battery — don’t touch it', c: 'stop', why: 'A cracked, leaking, swollen or hot battery can release acid and explosive gas.', step: 'Don’t jump-start or charge it, and don’t touch it. Arrange a tow or a mobile mechanic to replace it.', safe: 'Keep sparks and flames away. Battery acid burns skin and eyes.', diff: 'pro', drive: 'no', need: 'Battery replacement and inspection of cables and charging system' };
  R.x_wrongFuel = { t: 'Wrong fuel possible — don’t keep trying to start', c: 'stop', why: 'Gasoline in a diesel engine (or diesel in a gasoline engine) can damage the fuel system, and running it makes the damage worse.', step: 'Don’t crank or drive the car. Call a tow service and tell the shop what fuel went in and how much.', diff: 'pro', drive: 'no', need: 'Fuel system drain and inspection' };
  R.x_bulge = { t: 'Damaged tire — don’t drive on it', c: 'stop', why: 'A bulge, bubble or cut on the side of a tire means its internal structure is damaged. It can burst without warning.', step: 'Put on the spare if you have one and know how, or call roadside assistance. Replace the damaged tire — sidewall damage generally can’t be safely repaired.', diff: 'beginner', drive: 'no', need: 'Tire replacement; check wheel for damage' };
  R.x_flatDriving = { t: 'Slow down and pull over safely', c: 'stop', why: 'Driving on a flat tire can damage the wheel and make the car hard to control.', step: 'Hold the steering wheel firmly, ease off the gas (don’t brake hard), turn on hazard lights, and pull well off the road onto a flat surface. Then come back and choose “Stopped in a safe place”.', diff: 'emergency', drive: 'no' };
  R.x_stallDriving = { t: 'Stalling while driving is dangerous', c: 'stop', why: 'When the engine stops while moving, power steering and power brakes can become much heavier, though they still work with more effort.', step: 'If it happens: turn on hazards, steer firmly, press the brake hard, and coast to a safe place. Until it is fixed, avoid driving — especially on highways. Have it towed to a shop and give them this report.', diff: 'pro', drive: 'no', need: 'Scan for trouble codes; fuel, ignition and charging system tests' };

