 R.r_nsHelp = { t: 'We need a little more information', c: 'insufficient', why: 'Without knowing what happens when you try to start, we can’t narrow it down safely.', step: 'Ask someone to try starting while you listen, or record a short video with sound on your phone. Then start this guide again, or show the video to a mechanic.', diff: 'beginner', drive: '' };
  R.r_terminal = { t: 'A loose or corroded battery connection is likely', c: 'strong', why: 'You saw buildup, looseness or damage at the battery. That can block the large current the starter needs, even when the battery itself is fine.', unk: 'The battery may also be weak. That can only be confirmed with a battery test.', step: 'Have the battery clamps cleaned and tightened, then have the battery charged and tested. Many auto parts stores test batteries, often at no charge.', diff: 'tools', tools: 'Battery terminal brush, basic wrenches, eye protection — only if you know how to do this safely. Otherwise a shop or roadside service can do it.', safe: 'Never let a metal tool touch both battery posts at once. Disconnect the negative (–) clamp first and reconnect it last. Wear eye protection.', drive: '', need: 'Battery load test after cleaning; charging system test', tech: ['With ignition off, inspect battery clamps for corrosion, looseness, or broken cables.', 'If the battery is cracked, leaking, swollen, or hot, stop and request professional service.', 'Have loose or corroded connections cleaned and tightened to vehicle specification.', 'Retest starting and verify the charging system.'] };
  R.r_jumpWorked = { t: 'Low battery charge is likely — the cause still needs checking', c: 'strong', why: 'The car started once it had extra power, so the starter and engine are probably fine.', unk: 'A successful jump doesn’t prove the battery is bad. It may be worn out, or it may not be getting recharged (charging system), or something drained it.', step: 'Keep the engine running for a while so the battery can recharge, then have the battery and charging system tested soon. If it won’t restart later, don’t keep jumping it — get it tested.', diff: 'beginner', tools: 'None for you — a parts store or shop does the test', drive: 'caution', need: 'Battery load test; charging system (alternator) output test; key-off drain test if it keeps happening', tech: ['Have the 12V battery fully charged and tested under load; a successful jump-start alone does not prove the battery is bad.', 'Inspect battery terminals and main grounds.', 'After starting, test charging voltage/output using the vehicle-specific procedure.', 'If the battery discharges again, test for excessive key-off current draw.'] };
  R.r_jumpFailed = { t: 'The problem may be beyond the battery', c: 'possible', why: 'A correctly connected jump usually starts a car whose only problem is a flat battery. Since it didn’t, the starter, its wiring, a poor connection, or the security system may be involved.', unk: 'A jump can also fail if the cables were poor or badly connected, so this is not certain.', step: 'Have a mechanic or mobile mechanic test the battery, the cables and the starter before replacing any parts. Show them this report.', diff: 'pro', drive: '', need: 'Battery load test; starter cable voltage-drop test; starter current draw test', tech: ['Request a battery state-of-health/load test and starter current test.', 'Ask for the measured battery voltage during crank, not just resting voltage.', 'If battery passes, test cable voltage drop and starter mechanical load.'] };
  R.r_needJump = { t: 'Next step: a jump-start or a battery test', c: 'insufficient', why: 'Your answers fit a weak or flat battery, which is the most common cause, but we can’t confirm it without a jump or a test.', step: 'Call roadside assistance (often included with car insurance, auto clubs, or new-car warranties) for a jump or a battery test. If you own a portable jump pack, follow its instructions and your owner’s manual.', diff: 'beginner', drive: '', need: 'Jump-start attempt or battery test', tech: ['Check that lights, accessories, and doors were not left on.', 'Look for visibly loose or corroded battery connections without touching damaged components.', 'Arrange a 12V battery load test at a service location.', 'Use the results to decide whether to test cables, starter, or charging system.'] };
  R.r_drained = { t: 'A drained battery is likely', c: 'strong', why: 'Rapid clicking plus the car sitting or something left on is the classic pattern of a battery that has run down.', unk: 'If it happens again without a clear reason, the battery may be worn out or something may be draining it.', step: 'Jump-start or charge the battery (or call roadside assistance). Then have the battery tested to make sure it can still hold a charge.', diff: 'beginner', drive: 'caution', need: 'Battery load test' };
  R.r_range = { t: 'Park/Neutral switch or shifter problem is likely', c: 'strong', why: 'The car started in Neutral but not in Park. That points to the switch or linkage that tells the car it’s in Park.', step: 'Starting in Neutral (foot on brake) may get you going for now — check your owner’s manual first. Have the shifter and park/neutral switch checked soon.', safe: 'Never bypass this safety switch. It prevents the car from starting in gear.', diff: 'pro', drive: 'caution', need: 'Transmission range switch and shift linkage inspection', tech: ['Check whether the dashboard correctly displays Park and Neutral.', 'Request range-switch/interlock input testing.', 'Do not bypass the neutral-safety or clutch switch.'] };
  R.r_starter = { t: 'Starter or starter wiring problem is possible', c: 'possible', why: 'A single click with headlights that stay bright suggests the battery has power, but that power isn’t making the engine turn.', unk: 'A poor battery connection, a weak battery, the starter relay, or a security problem can all produce a single click. Testing is needed before replacing the starter.', step: 'Have a mechanic test the starter circuit. Avoid repeated start attempts.', safe: 'Don’t tap or hit the starter, and don’t try to bypass wiring — it can cause sparks or sudden engine movement.', diff: 'pro', drive: '', need: 'Battery load test; starter feed and ground voltage-drop test; starter command (relay) test; starter current draw', tech: ['Measure positive-side voltage drop from battery post to starter feed while cranking.', 'Measure ground-side voltage drop from starter case to battery negative post.', 'Test starter relay command and output with a wiring diagram; check related fuses.', 'Verify the engine rotates freely before condemning the starter.', 'Replace or repair the starter only after supply, command, and mechanical load are verified.'] };
  R.r_basicsOk = { t: 'It started after checking the shifter and brake', c: 'strong', why: 'Many cars won’t start unless the shifter is fully in Park and the brake is pressed firmly.', step: 'No repair may be needed. If it keeps happening even when you do these things correctly, have the brake switch and shifter checked.', diff: 'beginner', drive: 'ok' };
  R.r_keyFault = { t: 'A problem with your main key or fob is likely', c: 'strong', why: 'The spare key works and the main one doesn’t, so the car’s security system is fine — the main key is the issue.', step: 'Replace the battery in the main fob (the type is usually printed on the old battery or listed in the manual). If it still isn’t recognized, a dealer or automotive locksmith can test or reprogram it.', diff: 'beginner', tools: 'Replacement coin battery, small screwdriver for some fobs', drive: 'ok' };
  R.r_immob = { t: 'Security (immobilizer) system problem is possible', c: 'possible', why: 'The security light is involved and neither key works, so the problem is more likely in the car’s security system than in a single key.', unk: 'Both keys could have weak batteries, or a weak car battery can confuse the system.', step: 'Have a dealer or automotive locksmith scan the security system.', safe: 'Don’t use “bypass” devices — they can cause other problems and reduce theft protection.', diff: 'pro', drive: '', need: 'Immobilizer / key authorization scan', tech: ['Observe the security/key indicator during a start attempt.', 'Check the owner manual for the exact indicator meaning and approved key-relearning procedure.', 'Request a scan of immobilizer authorization data and key/antenna circuits.'] };
  R.r_immobMaybe = { t: 'Key or security problem is possible', c: 'insufficient', why: 'The security light is involved, but without a spare key we can’t tell whether the key or the car is at fault.', step: 'Replace the key fob battery first. For push-button cars, the owner’s manual usually describes a backup start method (such as holding the fob against the start button). If it still won’t start, have the security system checked.', diff: 'beginner', drive: '', need: 'Key battery replacement; immobilizer scan if still not recognized' };
  R.r_fuel = { t: 'The car may be out of fuel', c: 'possible', why: 'An engine that turns over normally but won’t start is often simply out of fuel, and gauges near empty aren’t always accurate.', step: 'Add a few gallons of the correct fuel (it’s marked inside the fuel door or in the manual) and try again. Try in short attempts — about 10 seconds at a time with a short rest between.', safe: 'Only refuel with the engine off. No smoking.', diff: 'beginner', drive: '', need: 'If it still won’t start with fuel: scan for codes, spark test, fuel pressure test', tech: ['Check the fuel gauge and, if safe, verify fuel is present; do not rely solely on the gauge.', 'If fuel is present and the engine still will not start, continue with fuel/spark/engine-management diagnosis.'] };
  R.r_ecuPower = { t: 'The engine computer may not be getting power', c: 'possible', why: 'The check-engine light normally comes on briefly at key-on. If it never does, the engine computer, its fuse or relay, or its wiring may be at fault.', unk: 'Some cars don’t show this bulb check clearly, so this answer is only a clue.', step: 'Have a mechanic check engine-computer power and ground, fuses and relays. Bring this report.', diff: 'advanced', drive: '', need: 'ECM power/ground and fuse/relay checks; scan tool communication check' };
  R.r_refuel = { t: 'Problem related to refueling', c: 'possible', why: 'A problem that appears right after getting fuel points to either the wrong fuel or the fuel vapor system.', unk: 'We can’t tell which without checking the receipt and testing.', step: 'Check your receipt. If the wrong fuel went in (diesel vs. gasoline), don’t keep cranking — get a tow. Otherwise, have the evaporative (EVAP) system checked; a stuck purge valve is a known cause of hard starting after refueling.', diff: 'pro', drive: '', need: 'EVAP purge valve flow test', tech: ['Note whether the problem follows refueling.', 'Have EVAP purge flow tested while the valve is commanded closed.', 'If the valve leaks when it should seal, repair/replace it.', 'Verify hot and post-refueling restarts.'] };
  R.r_crankPro = { t: 'Engine turns but doesn’t run — technician testing needed', c: 'insufficient', why: 'The starter and battery seem to be working. To run, an engine needs fuel, spark, air, compression and the right computer signals. Checking those requires equipment.', step: 'Have a mechanic read trouble codes and test for spark and fuel pressure. Bring this report. Avoid cranking over and over — it drains the battery and can flood the engine.', diff: 'advanced', drive: '', need: 'Scan for codes; engine RPM signal while cranking; spark test; fuel pressure test; injector command; compression test if needed', tech: ['Observe engine RPM in scan data during cranking; if absent, test crank sensor power, ground, signal and wiring.', 'Use a manufacturer-approved spark tester; never hold an ignition wire or coil while cranking.', 'Measure fuel pressure against the exact vehicle specification; test pump fuse, relay/module command, supply voltage and ground.', 'Verify injector command during cranking; check immobilizer authorization and cam/crank synchronization.', 'If spark and fuel are present, check compression and mechanical timing.', 'Document the failed test before replacing any component.'] };
  R.r_gradual = { t: 'Gradually harder starting — needs testing', c: 'possible', why: 'A problem that slowly gets worse often comes from wear: a weakening battery, a tired fuel pump, ignition parts, or a sensor.', step: 'Have the battery tested and the trouble codes read. Mention that it has been getting worse over time.', diff: 'tools', drive: 'caution', need: 'Battery test; scan for codes; fuel pressure test' };
  R.r_cold = { t: 'Cold-weather starting problem', c: 'possible', why: 'Cold weather reduces battery power and makes engines harder to turn. Diesels also depend on glow plugs and can have fuel thickening in severe cold.', step: 'Have the battery tested — a weak battery often shows up first in cold weather. For a diesel, wait for the glow plug light to go out before cranking, and ask a shop about winter-blend fuel.', diff: 'beginner', drive: '', need: 'Battery load test; glow plug system test (diesel)' };
  R.r_grind = { t: 'Stop trying to start it — grinding can damage parts', c: 'stop', why: 'Grinding usually means the starter’s small gear isn’t meshing properly with the engine’s large gear (flywheel).', step: 'Don’t keep trying. Have the starter and flywheel gear inspected by a mechanic.', diff: 'pro', drive: 'no', need: 'Starter drive and flywheel ring gear inspection', tech: ['Have starter mounting and pinion engagement inspected.', 'Inspect ring-gear teeth and check whether the starter remains engaged after the engine starts.', 'Repair the verified mechanical/control defect before another start attempt.'] };
  R.r_engage = { t: 'The starter is spinning but not turning the engine', c: 'strong', why: 'A high whir with no engine movement means the starter motor runs but its gear isn’t engaging the engine.', step: 'Stop repeated attempts and have the starter inspected — this usually needs a mechanic.', diff: 'pro', drive: '', need: 'Starter drive/pinion inspection', tech: ['Confirm that the starter motor spins while the crankshaft stays stationary.', 'Have the starter drive, mounting, pinion, and flywheel/flexplate ring gear inspected.'] };
  R.r_flashCel = { t: 'Severe engine misfire possible — stop driving', c: 'stop', why: 'A flashing check-engine light usually means a severe misfire. Unburned fuel can overheat and damage the catalytic converter (an expensive exhaust part).', step: 'Slow down, get off the road safely, and avoid driving further. Have the trouble codes read and the misfire diagnosed.', diff: 'pro', drive: 'no', need: 'Scan for codes and misfire data; ignition, injector and compression tests on affected cylinders', tech: ['Record codes and cylinder-specific misfire data.', 'Test ignition, injector operation, and compression on the affected cylinders.', 'Verify the repair without prolonged misfire operation.'] };
  R.r_codes = { t: 'Next step: read the trouble codes', c: 'insufficient', why: 'When the check-engine light is on, the car’s computer has stored a trouble code that points toward the problem area.', unk: 'A code points to a system or circuit — it doesn’t prove which part has failed.', step: 'Have the codes read (many auto parts stores do this, or use an OBD-II scanner). Write down the exact codes, such as “P0301”, and bring them with this report.', diff: 'tools', tools: 'OBD-II scanner (or a free code reading at a parts store)', drive: 'caution', need: 'Scan for stored and pending codes with freeze-frame data', tech: ['Record the exact diagnostic trouble codes, including pending codes and freeze-frame data.', 'Do not assume a code names the failed part; follow the code diagnostic chart.', 'Check relevant live data during the symptom and verify the suspected circuit.', 'Retest after repair and confirm the fault does not return.'] };
  R.r_diePro = { t: 'Starts then dies — technician testing needed', c: 'insufficient', why: 'An engine that starts and immediately dies, with no warning lights, can have a fuel delivery, air intake or idle control problem.', step: 'Have a mechanic check fuel pressure, idle and throttle control, and for air leaks. Mention whether it stays running if you press the gas lightly.', diff: 'advanced', drive: 'no', need: 'Fuel pressure test; idle/throttle inspection; intake leak check', tech: ['Check whether the engine stays running with light accelerator input.', 'Inspect throttle body, idle-air-control system (if fitted), and intake leaks.', 'Check idle-control data and fuel trims with a scanner.', 'Use the manufacturer cleaning/relearn procedure if indicated.'] };
  R.r_glowWait = { t: 'Wait for the glow plug light before starting', c: 'possible', why: 'Diesels need their glow plugs to warm up first, especially when cold. Starting too early often fails.', step: 'Turn the key to ON and wait until the coil-shaped light goes out, then start. In cold weather it can take longer. If it still won’t start, run this guide again and choose “Yes, and it still won’t start”.', diff: 'beginner', drive: '' };
  R.r_glowFault = { t: 'Glow plug or engine-control problem possible', c: 'possible', why: 'On many diesels, a glow plug light that flashes or stays on signals a fault in the glow plug system or engine controls.', step: 'Have the trouble codes read by a shop familiar with diesels.', diff: 'pro', drive: 'caution', need: 'Diesel scan; glow plug circuit test' };
  R.r_dieselDry = { t: 'Diesel ran out of fuel — it may need priming', c: 'possible', why: 'After running dry, many diesels draw air into the fuel system and won’t restart until the air is removed (“bleeding” or “priming”).', step: 'Add diesel fuel. Check your owner’s manual for a priming procedure; if there isn’t one or you’re unsure, call a mechanic. Avoid long cranking, which can overheat the starter.', diff: 'tools', drive: '', need: 'Fuel system priming' };
  R.r_dieselPro = { t: 'Diesel no-start needs professional testing', c: 'insufficient', why: 'Diesel starting depends on fuel delivery at high pressure, glow plugs and engine controls — checking these needs diesel-specific equipment.', step: 'Have a diesel-capable shop scan the engine and test fuel delivery and glow plugs.', diff: 'pro', drive: '', need: 'Diesel scan; fuel delivery/pressure test; glow plug test' };
  R.r_hotStart = { t: 'Starting fails only when warm — needs testing', c: 'possible', why: 'Problems that appear only when the engine is warm can come from a starter that struggles with heat, fuel vapor issues, or a sensor that fails when hot.', step: 'Tell the mechanic exactly that it fails when warm, and ask them to test while the engine is hot.', diff: 'pro', drive: 'caution', need: 'Hot-condition starter current test; scan for codes; fuel pressure hold test' };
  R.r_interPro = { t: 'Intermittent starting problem — needs testing during a failure', c: 'insufficient', why: 'Problems that come and go are hard to find unless they can be observed while happening.', step: 'Each time it fails, note what happens (sound, lights, weather, engine warm or cold). Have the battery tested and codes read, and give your notes and this report to a mechanic.', diff: 'pro', drive: 'caution', need: 'Battery test; scan for codes; test during a failure if possible' };
  R.r_ev12 = { t: 'The small 12-volt battery may be flat', c: 'possible', why: 'Even electric cars use a small 12-volt battery to power locks, screens and computers. If it’s flat, the car can seem completely dead even with a charged main battery.', unk: 'A key or software problem can look similar.', step: 'Check your owner’s manual for how to get in with a dead key (mechanical key or card) and how to jump or charge the 12-volt battery — many EVs have a specific connection point. If unsure, call the manufacturer’s roadside assistance.', safe: 'Never touch orange high-voltage cables or components.', diff: 'tools', drive: '', need: '12-volt battery test' };
  R.r_evHv = { t: 'High-voltage system warning — professional service needed', c: 'stop', why: 'A warning about the main battery or drive system means the car has detected a fault in high-voltage parts.', step: 'Don’t try to fix anything. Contact the manufacturer’s roadside assistance or an authorized service center. Note the exact message.', safe: 'Never touch orange cables. If you see smoke or hear popping or hissing, move away and call emergency services.', diff: 'pro', drive: 'no', need: 'High-voltage system diagnosis by a trained technician' };
  R.r_evBasics = { t: 'It worked after checking the basics', c: 'strong', why: 'Electric cars won’t go into Drive if the charging cable is connected, the brake isn’t pressed, or the key isn’t detected.', step: 'No repair may be needed. If it keeps happening, have the key and brake switch checked.', diff: 'beginner', drive: 'ok' };
  R.r_evEmpty = { t: 'The main battery may be too low to drive', c: 'strong', why: 'Many electric cars won’t go into Drive when the main battery is nearly empty.', step: 'Arrange a tow to a charger, or a mobile charging service if available. Some roadside services offer this.', diff: 'beginner', drive: 'no' };
  R.r_evPro = { t: 'Electric car won’t drive — service needed', c: 'insufficient', why: 'With enough charge and the basics checked, the cause is likely a fault the car’s systems must be scanned for.', step: 'Contact the manufacturer’s roadside assistance or service center. Note any messages shown on the screen.', diff: 'pro', drive: '', need: 'Manufacturer diagnostic scan' };
  R.r_hyReady = { t: 'Your hybrid is probably on and working', c: 'strong', why: 'Hybrids are often silent at startup. READY means the car is on; the gasoline engine starts by itself when needed.', step: 'With your foot on the brake, select Drive and go. If READY appears but the car won’t move, choose a different answer or contact service.', diff: 'beginner', drive: 'ok' };
  R.r_hy12 = { t: 'The hybrid’s 12-volt battery may be weak', c: 'possible', why: 'Hybrids rely on a small 12-volt battery to turn on their systems. When it’s weak, the dashboard may light but READY never appears, or nothing lights at all.', unk: 'A key or brake switch problem can look similar.', step: 'Check your owner’s manual for how to jump-start your hybrid — many use specific jump points under the hood. If unsure, call roadside assistance. Have the 12-volt battery tested afterward.', safe: 'Use only the jump points shown in the manual. Never touch orange high-voltage cables.', diff: 'tools', drive: '', need: '12-volt battery test' };
  R.r_hyHv = { t: 'Hybrid system warning — professional service needed', c: 'stop', why: 'A hybrid system warning means a fault was detected in high-voltage or drive-system parts.', step: 'Contact the dealer or a hybrid-qualified shop. Note the exact message.', safe: 'Never touch orange cables or high-voltage parts.', diff: 'pro', drive: 'no', need: 'Hybrid system diagnosis by a trained technician' };
  R.r_charging = { t: 'A charging system (alternator) problem is possible', c: 'possible', why: 'Dimming lights, flickering, or a battery warning light while driving suggest the battery isn’t being recharged properly.', unk: 'A worn battery or a loose belt or connection can cause similar signs.', step: 'Have the charging system and battery tested soon. Until then, avoid long trips and turn off unneeded electrical items — the car could stall if the battery runs down.', diff: 'tools', drive: 'caution', terms: ['alt'], need: 'Charging system output test; battery test; drive belt inspection' };

 /* ---------- WARNING LIGHTS ---------- */
 N.wl_start = { q: 'What color is the warning light?', help: 'Red usually means a serious problem — stop soon. Yellow or orange means get it checked soon. Green, blue or white lights are usually just information, such as headlights being on.', pic: 'dash', photo: true, opts: [
   ['Red', 'wl_red'], ['Yellow or orange', 'wl_yel'], ['Green, blue, or white', 'r_wlInfo'], ['I’m not sure', 'wl_shape']] };
  N.wl_red = { q: 'Which red light is it closest to?', pic: 'dash', photo: true, opts: [
    ['A thermometer in liquid (engine temperature)', 'oh_now', FUEL],
    ['An oil can (oil pressure)', 'r_wlOil', FUEL],
    ['A battery shape', 'r_wlBatt'],
    ['The word BRAKE, or ! inside a circle', 'bk_light'],
    ['Something else, or I’m not sure', 'r_wlRed']] };
  N.wl_yel = { q: 'Which yellow or orange light is it closest to?', pic: 'dash', photo: true, opts: [
    ['An engine outline (check engine)', 'wl_cel', FUEL],
    ['A tire cross-section with ! (tire pressure)', 'ti_tpms'],
    ['The letters ABS', 'r_wlAbs'],
    ['Something else, or I’m not sure', 'r_wlYel']] };
  N.wl_shape = { q: 'Which shape is it closest to?', pic: 'dash', photo: true, opts: [
    ['An engine outline', 'wl_cel', FUEL], ['An oil can', 'r_wlOil', FUEL], ['A thermometer', 'oh_now', FUEL], ['A battery', 'r_wlBatt'],
    ['A tire with !', 'ti_tpms'], ['BRAKE, or ! inside a circle', 'bk_light'], ['I can’t tell', 'r_wlPhoto']] };
  N.wl_cel = { q: 'Is the check-engine light steady or flashing?', terms: ['cel'], opts: [
    ['Flashing', 'r_flashCel'], ['Steady', 'wl_drive'], ['I’m not sure', 'wl_drive']] };
  N.wl_drive = { q: 'Is the car driving differently — shaking, weak, or smelling odd?', opts: [
    ['Yes', 'r_celSym'], ['No, it drives normally', 'wl_cap'], ['I’m not sure', 'r_codes']] };
  N.wl_cap = { q: 'Did you get fuel in the last few days?', help: 'A fuel cap that isn’t fully tightened can turn on the check-engine light on many cars.', opts: [
    ['Yes', 'r_gasCap'], ['No', 'r_codes'], ['I don’t remember', 'r_gasCap']] };
  R.r_wlInfo = { t: 'Green, blue or white lights are usually information only', c: 'strong', why: 'These colors normally show that something is switched on, such as headlights, high beams or cruise control.', step: 'Look up the symbol in the “indicators” section of your owner’s manual to be sure.', diff: 'beginner', drive: 'ok' };
  R.r_wlOil = { t: 'Oil pressure warning — turn the engine off', c: 'stop', why: 'A red oil light means the engine may not be getting oil pressure. Driving without oil pressure can destroy an engine within minutes.', step: 'Pull over safely and switch off the engine as soon as you can. After 5–10 minutes, check the oil level (see “Show me what that looks like”). If it’s low, add the oil type listed in your manual. If the light stays on after adding oil, or the oil level was fine, don’t drive — have it towed.', pic: 'dipstick', safe: 'Engine parts can be hot. Check the oil only with the engine off.', diff: 'beginner', drive: 'no', need: 'Oil level check; oil pressure test' };
  R.r_wlBatt = { t: 'Charging system warning', c: 'possible', why: 'The red battery light usually means the battery isn’t being recharged while the engine runs, so the car is using up stored battery power.', unk: 'On hybrid and electric cars, this light can mean a 12-volt system fault — check the manual.', step: 'Turn off unneeded electrical items (A/C, heated seats, radio) and drive directly to a shop or home. The car could stall when the battery runs down. Have the alternator, belt and battery checked.', diff: 'tools', drive: 'caution', terms: ['alt'], need: 'Charging system output test; drive belt inspection; battery test' };
  R.r_wlRed = { t: 'Red warning — check the owner’s manual now', c: 'insufficient', why: 'Red lights usually mean a problem that needs attention right away, but the meaning depends on the symbol.', step: 'Pull over somewhere safe and look the symbol up in the “warning lights” section of your owner’s manual. If you can’t identify it and the car behaves strangely, don’t keep driving.', diff: 'beginner', drive: 'caution' };
  R.r_wlAbs = { t: 'Anti-lock brake (ABS) warning', c: 'possible', why: 'The ABS light means the anti-lock function may be switched off because of a fault.', unk: 'Normal braking usually still works, but if the red BRAKE light is also on, the brake system itself may have a problem.', step: 'Drive gently and leave extra stopping distance. Have the ABS system scanned soon. If the red BRAKE light is also on, don’t drive — use the Brake section.', diff: 'pro', drive: 'caution', need: 'ABS module scan; wheel speed sensor checks' };
  R.r_wlYel = { t: 'Yellow warning — check soon', c: 'insufficient', why: 'Yellow and orange lights usually mean something needs attention soon, but not necessarily right now.', step: 'Look the symbol up in the “warning lights” section of your owner’s manual. You can also add a photo below for your report and show it to a mechanic.', diff: 'beginner', drive: 'caution' };
  R.r_wlPhoto = { t: 'Let’s identify the symbol first', c: 'insufficient', why: 'Warning lights mean very different things, and we can’t tell which one it is yet.', step: 'Take a photo of the light (you can add it below to keep with your report), then look it up in the “warning lights” section of your owner’s manual. Red means stop soon; yellow means check soon.', diff: 'beginner', drive: '' };
  R.r_celSym = { t: 'Check-engine light with driving symptoms', c: 'possible', why: 'A steady check-engine light plus shaking, weakness or odd smells suggests an active engine problem.', step: 'Have the trouble codes read soon and avoid long trips until then. If the light starts flashing, stop driving.', diff: 'tools', drive: 'caution', terms: ['obd'], need: 'Scan for codes with freeze-frame data' };
  R.r_gasCap = { t: 'A loose fuel cap is a possible cause', c: 'possible', why: 'A cap that isn’t sealed can trigger the light after refueling, and the car drives normally.', unk: 'Many other problems can turn on the same light.', step: 'Make sure the fuel cap clicks tight (or the capless filler closed properly). The light may take several days of normal driving to go off by itself. If it’s still on after about a week, have the codes read.', diff: 'beginner', drive: 'ok', need: 'Code scan if the light stays on' };

 /* ---------- OVERHEATING ---------- */
 N.oh_start = { q: 'What are you noticing?', opts: [
   ['The temperature gauge is high, or a temperature warning light is on', 'oh_now'],
   ['Steam coming from under the hood', 'x_steam'],
   ['A sweet smell, or green, orange, or pink drips under the car', 'oh_leak'],
   ['The heater blows cold air while the gauge reads high', 'r_ohCirc'],
   ['I’m not sure', 'oh_now']] };
  N.oh_now = { q: 'Is the engine running right now?', opts: [
    ['Yes, I’m driving or the engine is running', 'x_hot'], ['No, the engine is off', 'oh_cool']] };
  N.oh_cool = { q: 'Has the engine been off for at least 30 minutes?', help: 'The cooling system is under pressure when hot. Opening it can spray scalding coolant.', terms: ['coolant'], opts: [
    ['Yes, it has cooled down', 'oh_level'], ['No', 'r_ohWait']] };
  N.oh_level = { q: 'Look at the coolant overflow tank. Where is the coolant level?', pic: 'reservoir', look: {
    what: 'A see-through plastic tank holding colored liquid, with MIN and MAX (or LOW and FULL) marks on its side.',
    where: 'Under the hood, usually near the front or one side of the engine. The cap often has a warning symbol or says “coolant”.',
    how: 'Compare the liquid level with the marks on the side of the tank. You don’t need to open anything.',
    cant: 'Look up “coolant” in your owner’s manual. If you still can’t find it, choose “I can’t find it”.',
    safe: 'Look only. Never open the radiator cap or the tank cap on a warm engine.' }, opts: [
    ['Below MIN, or the tank is empty', 'oh_leak', T1], ['Between MIN and MAX', 'oh_when', T1], ['I can’t find it or can’t tell', 'r_ohPro']] };
  N.oh_leak = { q: 'Is there a puddle or drips under the front of the car?', pic: 'fluids', photo: true, opts: [
    ['Yes', 'r_ohLeak'], ['No', 'r_ohLowNoLeak'], ['I’m not sure', 'r_ohLowNoLeak']] };
  N.oh_when = { q: 'When does it run hot?', opts: [
    ['Mostly when stopped in traffic or idling', 'r_ohFan'], ['Mostly at highway speed, towing, or climbing hills', 'r_ohFlow'], ['The gauge jumps around, or reads high but the car seems fine', 'r_ohGauge'], ['I’m not sure', 'r_ohPro']] };
  R.r_ohWait = { t: 'Wait until the engine has cooled', c: 'stop', why: 'A hot cooling system is under pressure. Opening or touching it can cause serious burns.', step: 'Keep the hood closed and wait at least 30 minutes. Then start this section again.', safe: 'Never open the radiator or coolant cap while hot.', diff: 'beginner', drive: 'no' };
  R.r_ohLeak = { t: 'A coolant leak is likely', c: 'strong', why: 'The coolant is low and there’s fluid under the front of the car. Losing coolant is a common reason engines overheat.', unk: 'We can’t tell from here where the leak is (hose, radiator, water pump, or elsewhere).', step: 'Don’t drive far. If the engine is fully cool, you can top up to the MAX mark with the coolant type listed in your owner’s manual as a temporary measure, then have the leak found and repaired.', safe: 'Coolant is poisonous to children and pets and tastes sweet — clean up puddles. Never open the cap on a warm engine.', diff: 'beginner', drive: 'caution', need: 'Cooling system pressure test to locate the leak' };
  R.r_ohLowNoLeak = { t: 'Coolant is low, but no leak is visible', c: 'possible', why: 'Coolant can be lost through small leaks that evaporate before dripping, or internally inside the engine.', unk: 'Internal coolant loss (for example a head gasket problem) can only be confirmed with testing.', step: 'When the engine is cool, top up to MAX with the coolant type in your owner’s manual. Check the level again after each drive. If it keeps dropping, have a cooling system pressure test done.', safe: 'Only open the cap on a fully cool engine.', diff: 'beginner', drive: 'caution', need: 'Cooling system pressure test; combustion leak test' };
  R.r_ohFan = { t: 'A cooling fan problem is possible', c: 'possible', why: 'When the car is stopped, there’s little air flowing through the radiator, so the cooling fan does the work. Overheating mainly in traffic points to the fan.', unk: 'Low coolant or a blocked radiator can cause similar symptoms.', step: 'Have a mechanic check that the cooling fan turns on when the engine is hot.', safe: 'Keep hands, hair and clothing away from the fan. On many cars the fan can start without warning, even with the engine off.', diff: 'pro', drive: 'caution', need: 'Cooling fan operation test; fan relay/fuse check' };
  R.r_ohFlow = { t: 'Restricted coolant flow or airflow is possible', c: 'possible', why: 'Overheating under heavy load suggests the system can’t move enough heat — for example a blocked radiator, a sticking thermostat, or a weak water pump.', step: 'Have a mechanic inspect the radiator, thermostat and water pump. Avoid towing or long hill climbs until then.', diff: 'pro', drive: 'caution', need: 'Radiator flow/temperature check; thermostat test; water pump inspection' };
  R.r_ohGauge = { t: 'A temperature sensor or gauge problem is possible', c: 'possible', why: 'A gauge that jumps around, or reads high while the car seems normal, can mean the reading is wrong rather than the engine.', unk: 'We can’t rule out real overheating without measuring the engine temperature.', step: 'Have a shop compare the gauge with the actual engine temperature using a scan tool. Treat the gauge as real until it’s checked.', diff: 'pro', drive: 'caution', need: 'Scan-tool coolant temperature comparison; sensor/gauge circuit check' };
  R.r_ohCirc = { t: 'Low coolant or poor circulation is likely', c: 'possible', why: 'When the engine is hot but the heater blows cold, hot coolant often isn’t reaching the heater — commonly because coolant is low.', step: 'Stop driving and let the engine cool for at least 30 minutes. Then check the coolant level using the Overheating section, and have the system inspected.', safe: 'Never open the coolant cap while hot.', diff: 'pro', drive: 'no', need: 'Coolant level check; cooling system pressure test; water pump inspection' };
  R.r_ohPro = { t: 'Overheating — have the cooling system inspected', c: 'insufficient', why: 'The engine is running hot, but your answers don’t point to one cause.', step: 'Avoid driving until it’s checked. Have a mechanic check the coolant level, look for leaks, and test the fan, thermostat and water pump.', diff: 'pro', drive: 'no', need: 'Cooling system inspection and pressure test' };
  R.r_evHeat = { t: 'Electric cars don’t have an engine cooling system like this', c: 'insufficient', why: 'Electric cars manage battery and motor temperature differently. Gasoline-engine overheating checks don’t apply.', step: 'If the car shows a temperature or battery warning, follow the message, park somewhere safe, and contact the manufacturer’s roadside assistance.', safe: 'Never open high-voltage system parts. If you see smoke or hear hissing or popping from the battery area, move away and call emergency services.', diff: 'pro', drive: '' };

 /* ---------- BATTERY KEEPS DYING ---------- */
